actions.command:
.venv/bin/python << 'EOF'
from marshmallow import validate

validator = validate.Finite()

# Test valid input: 0
try:
    result = validator(0)
    print(f"✓ 0 is valid: {result}")
except Exception as e:
    print(f"✗ 0 failed: {e}")

# Test invalid input: 1e309
try:
    result = validator(1e309)
    print(f"✗ 1e309 should be invalid but passed: {result}")
except Exception as e:
    print(f"✓ 1e309 is invalid: {e}")

# Test NaN
try:
    result = validator(float('nan'))
    print(f"✗ NaN should be invalid but passed: {result}")
except Exception as e:
    print(f"✓ NaN is invalid: {e}")

# Test infinity
try:
    result = validator(float('inf'))
    print(f"✗ inf should be invalid but passed: {result}")
except Exception as e:
    print(f"✓ inf is invalid: {e}")

# Test -infinity
try:
    result = validator(float('-inf'))
    print(f"✗ -inf should be invalid but passed: {result}")
except Exception as e:
    print(f"✓ -inf is invalid: {e}")

# Test custom error message with interpolation
validator_custom = validate.Finite(error="Value {input} is not finite!")
try:
    validator_custom(float('nan'))
except Exception as e:
    print(f"✓ Custom error message: {e}")
EOF
